import random
import string


class Cipher:
    def __init__(self, key=None):
        if key is None:
            # generate at least 100 lowercase letters
            self.key = ''.join(random.choice(string.ascii_lowercase) for _ in range(100))
        else:
            if not key or not all('a' <= ch <= 'z' for ch in key):
                raise ValueError("Key must consist of lowercase letters")
            self.key = key

    def encode(self, text):
        result = []
        key_len = len(self.key)
        key_index = 0

        for ch in text:
            if 'a' <= ch <= 'z':
                shift = ord(self.key[key_index % key_len]) - ord('a')
                encoded_ord = (ord(ch) - ord('a') + shift) % 26 + ord('a')
                result.append(chr(encoded_ord))
                key_index += 1
            else:
                # leave characters that are not lowercase letters unchanged
                result.append(ch)

        return ''.join(result)

    def decode(self, text):
        result = []
        key_len = len(self.key)
        key_index = 0

        for ch in text:
            if 'a' <= ch <= 'z':
                shift = ord(self.key[key_index % key_len]) - ord('a')
                decoded_ord = (ord(ch) - ord('a') - shift) % 26 + ord('a')
                result.append(chr(decoded_ord))
                key_index += 1
            else:
                # leave characters that are not lowercase letters unchanged
                result.append(ch)

        return ''.join(result)
